package ir.shipaa.android;
import android.app.Activity;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.PlayerView;
public class PlayerActivity extends Activity {
    ExoPlayer player;PlayerView video;String key;long position;boolean playing=true;float speed=1;Ui ui;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);ui=new Ui(this);key=getIntent().getStringExtra("key");position=getSharedPreferences("learner",0).getLong("position:"+key,0);if(saved!=null){position=saved.getLong("position",position);playing=saved.getBoolean("playing",true);speed=saved.getFloat("speed",1);}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        LinearLayout root=ui.col();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(0xff12271f);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in;});LinearLayout head=ui.row();head.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));head.addView(ui.iconButton("arrow","بازگشت",this::finish));TextView title=ui.text(getIntent().getStringExtra("title"),14,Ui.WHITE,true);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);video=new PlayerView(this);video.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);root.addView(video,new LinearLayout.LayoutParams(-1,0,1));LinearLayout speeds=ui.row();speeds.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(16));for(float f:new float[]{.75f,1f,1.25f,1.5f,2f}){TextView b=ui.action(f+"×",false,()->{speed=f;if(player!=null)player.setPlaybackSpeed(f);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(ui.dp(2),0,ui.dp(2),0);speeds.addView(b,lp);}root.addView(speeds);setContentView(root);
    }
    @Override protected void onStart(){super.onStart();player=new ExoPlayer.Builder(this).setSeekBackIncrementMs(10000).setSeekForwardIncrementMs(10000).build();video.setPlayer(player);player.setAudioAttributes(new AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);player.setHandleAudioBecomingNoisy(true);player.setMediaItem(MediaItem.fromUri(getIntent().getStringExtra("uri")));player.seekTo(position);player.setPlaybackSpeed(speed);player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){Toast.makeText(PlayerActivity.this,"پخش انجام نشد؛ اتصال یا فایل دانلودشده را بررسی کن",Toast.LENGTH_LONG).show();}});player.prepare();player.setPlayWhenReady(playing);}
    @Override protected void onStop(){if(player!=null){position=player.getCurrentPosition();playing=player.getPlayWhenReady();long duration=player.getDuration();android.content.SharedPreferences.Editor edit=getSharedPreferences("learner",0).edit().putLong("position:"+key,position);if(duration>0)edit.putLong("duration:"+key,duration);edit.apply();video.setPlayer(null);player.release();player=null;}super.onStop();}
    @Override public void onSaveInstanceState(Bundle out){out.putLong("position",player==null?position:player.getCurrentPosition());out.putBoolean("playing",player==null?playing:player.getPlayWhenReady());out.putFloat("speed",speed);super.onSaveInstanceState(out);}
}
